function gagal(pesan: string): never {
  throw new Error(pesan);
}
function ambilHarga(menu: string, daftar: Map<string, number>): number {
  const h = daftar.get(menu);
  if (h === undefined) {
    gagal(`Menu ${menu} tidak ada`);
  }
  return h;
}
const harga = new Map([["kopi", 18000]]);
console.log(ambilHarga("kopi", harga));
try {
  ambilHarga("jus", harga);
} catch (e) {
  if (e instanceof Error) console.log("Gagal:", e.message);
}

