questions.code:
function cek(pesan: string): never {
  throw new Error(pesan);
}
function ambil(x: string | undefined): string {
  if (x === undefined) cek("kosong");
  return x;
}
console.log(ambil("ok"));

function habis(): never {
  throw new Error("stok habis");
}
try {
  console.log("mulai");
  habis();
  console.log("selesai");
} catch (e) {
  if (e instanceof Error) console.log(e.name + ": " + e.message);
}

