cards.solution:
function gagal(pesan: string): never {
  throw new Error(pesan);
}
function wajibPositif(n: number, nama: string): number {
  if (n <= 0) gagal(`${nama} harus lebih dari 0`);
  return n;
}
console.log(wajibPositif(5, "Jumlah"));
try {
  wajibPositif(-1, "Harga");
} catch (e) {
  if (e instanceof Error) console.log(e.message);
}
